package net.civeira.phylax.features.document.themeasset.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.features.document.themeasset.domain.ThemeAsset;
import net.civeira.phylax.features.document.themeasset.domain.gateway.ThemeAssetCursor;
import net.civeira.phylax.features.document.themeasset.domain.gateway.ThemeAssetFilter;

class ThemeAssetSlider extends Slider<ThemeAsset> {

  /**
   * @autogenerated SlideGenerator
   */
  private final ThemeAssetCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final ThemeAssetFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<ThemeAssetFilter, ThemeAssetCursor, Iterator<ThemeAsset>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  ThemeAssetSlider(final Iterator<ThemeAsset> multi, final int limit,
      final BiFunction<ThemeAssetFilter, ThemeAssetCursor, Iterator<ThemeAsset>> gateway,
      final ThemeAssetFilter filter, final ThemeAssetCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param themeAssets
   * @param limit
   * @return
   */
  @Override
  public Iterator<ThemeAsset> next(List<ThemeAsset> themeAssets, int limit) {
    ThemeAsset last = themeAssets.get(themeAssets.size() - 1);
    ThemeAssetCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
